from lib import *
S = SS('j252')
steps = [
    step("本篇用 GraalVM CE 25.0.2(JDK 25.0.2+10-jvmci)里的同一个 JDK 比较三种编译配置,避免换 JDK 带来的其它差异:-XX:-UseJVMCICompiler -XX:TieredStopAtLevel=1 是只用 C1;-XX:-UseJVMCICompiler 是 C1 + C2;默认(UseJVMCICompiler = true,EnableJVMCI = true,UseJVMCINativeLibrary = true)是 C1 + Graal 作为顶层编译器(libgraal)。通过 HotSpotDiagnosticMXBean 读出的三组标志值与这三种配置一致。", t=tl(S(1)), done=lidx(S(1), 'C1(TieredStopAtLevel=1)'), mark=lidx(S(1), '[C2]', 'Graal JIT(默认)'), kv=KV([['C1', 'UseJVMCICompiler = false,TieredStopAtLevel = 1'], ['C2', 'UseJVMCICompiler = false'], ['Graal JIT(默认)', 'UseJVMCICompiler = true,UseJVMCINativeLibrary = true']], ['Graal JIT(默认)'])),
    step("逃逸分析(每次调用线程分配的字节数,24 字节 = 对象没被消除)。分支里新建的对象才会逃逸的 v3 与 v5:C2 与 Graal 都是 0 字节,C1 是 24 字节;Graal 加上 -Djdk.graal.PartialEscapeAnalysis=false 之后 v3、v5 都回到 24 字节——Graal 在这里靠的是部分逃逸分析。但我原本预期 Graal 能消除的“同一个对象只在罕见分支里逃逸”的 v1、v2、v4、v6:C2 与 Graal 在这次测试里都没有消除(24 字节),原因我没有查明。", t=tl(S(2)), done=lidx(S(2), '[C2]', 'Graal JIT(默认)]'), mark=lidx(S(2), 'PartialEscapeAnalysis=false', 'C1(TieredStopAtLevel=1)'), b=bars([['v3 / v5:C2 与 Graal', 0, '0 字节'], ['v3 / v5:Graal 关 PEA', 24, '24 字节'], ['v1 / v2 / v4 / v6:Graal', 24, '24 字节'], ['v1 / v2 / v4 / v6:C2', 24, '24 字节']], 24, done=[0, 1, 2, 3]), kv=KV([['v3 / v5(逃逸的是另一个对象 / 分支永不成立)', 'C2、Graal:0 字节;关 PEA 后 Graal:24 字节'], ['v1 / v2 / v4 / v6(同一个对象在罕见分支里逃逸)', '没有被消除,原因未查明']], ['v1 / v2 / v4 / v6(同一个对象在罕见分支里逃逸)'])),
    step("稳态吞吐(每毫秒完成的 work() 次数,7 轮取中位数):stream:C1 188.7、C2 857.8、Graal 654.3;poly2(双态调用):C1 384.7、C2 1386.5、Graal 423.9;poly3:C1 328.1、C2 339.6、Graal 353.9;string:C1 148.6、C2 409.8、Graal 167.1;hash:C1 148.5、C2 250.1、Graal 231.7。这一组里 C2 在 4 项上更快,Graal 只在 poly3 上略快(4%)。同样的程序在另一次运行里 Graal 的 poly2 是 844.7,所以单项数字会有明显波动。这是社区版 Graal、这几个小负载下的结果,不代表 Oracle GraalVM 或其它应用。", t=tl(S(3)), done=lidx(S(3), 'stream   每毫秒'), mark=lidx(S(3), 'poly2    每毫秒', 'string   每毫秒', 'hash     每毫秒'), b=bars([['stream:C2', 857.8, '857.8'], ['stream:Graal', 654.3, '654.3'], ['poly2:C2', 1386.5, '1386.5'], ['poly2:Graal', 423.9, '423.9'], ['string:C2', 409.8, '409.8'], ['string:Graal', 167.1, '167.1']], 1400, done=[0, 1, 2, 3, 4, 5]), kv=KV([['C2 更快', 'stream、poly2、string、hash'], ['Graal 更快', 'poly3(353.9 vs 339.6)'], ['波动', '同一程序另一次运行 Graal poly2 是 844.7']], ['C2 更快'])),
    step("预热曲线(stream 负载,每批 20000 次调用的耗时,毫秒):C1 一直是约 108 ms(第 1 批 112.2,第 40 批 108.3,前 40 批合计 4345 ms);C2 第 1 批 35.2,第 2 批 25.4,第 10 批 24.0,第 40 批 23.5,合计 984 ms;Graal 第 1 批 43.8,第 2 批 30.7,第 10 批 30.9,第 40 批 31.0,合计 1246 ms。两种顶层编译器都在第 2 批前后进入稳态,Graal 的稳态比 C2 慢约 30%。", t=tl(S(4)), done=lidx(S(4), '[C1(TieredStopAtLevel=1)]'), mark=lidx(S(4), '[C2]', '[Graal JIT(默认)]'), b=bars([['C1:前 40 批合计', 4345, '4345 ms'], ['C2:前 40 批合计', 984, '984 ms'], ['Graal:前 40 批合计', 1246, '1246 ms']], 4345, done=[0, 1, 2]), kv=KV([['C2', '第 1 批 35.2 ms → 稳态约 24 ms'], ['Graal', '第 1 批 43.8 ms → 稳态约 31 ms']], ['Graal'])),
    step("资源(同一个 6 秒 stream 负载,/usr/bin/time -l):C1 完成 1,104,000 次,峰值常驻内存 195 MiB,user 6.03 s;C2 完成 5,116,000 次,205 MiB,user 6.10 s;Graal 完成 3,950,000 次,250 MiB,user 6.11 s。Graal(libgraal)比 C2 多约 45 MiB 常驻内存;这个负载下 CPU 时间三者几乎一样(单线程负载几乎占满一个核),差别在完成的次数。", t=tl(S(5)), done=lidx(S(5), '[C1(TieredStopAtLevel=1)]'), mark=lidx(S(5), '[C2]', '[Graal JIT(默认)]'), b=bars([['C1:峰值内存', 195, '195 MiB'], ['C2:峰值内存', 205, '205 MiB'], ['Graal:峰值内存', 250, '250 MiB']], 250, done=[0, 1, 2]), kv=KV([['完成次数', 'C1 1.10 M / C2 5.12 M / Graal 3.95 M'], ['峰值内存', '195 / 205 / 250 MiB']], ['峰值内存'])),
]
A = mkartj('j252', 252, 'Java,JIT,Graal,C2,逃逸分析,JVMCI,真实验证,动画演示',
    '用 GraalVM CE 25.0.2 的同一个 JDK 比较 C1 / C2 / Graal JIT:分支内逃逸的对象 C2 与 Graal 都被消除、关掉 PEA 后 Graal 不再消除;原以为 Graal 能消除的“同一对象罕见分支逃逸”两者都没消除;5 个小负载里 C2 有 4 个更快;稳态 stream 每批 24 ms vs 31 ms;峰值内存 205 vs 250 MiB。',
    'Graal 是用 Java 写成、可以替换 C2 的 JIT 编译器。这篇在同一个 JDK 上只切换编译器,量出它的逃逸分析、稳态吞吐、预热曲线和内存成本,并如实记录一个预期没有出现的优化。',
    [('0 → 24 字节', '关闭 Graal 的部分逃逸分析后,分支内逃逸场景下每次调用的分配量'), ('4 / 5', '5 个小负载中 C2 比 Graal 更快的数量(社区版 Graal 25.0.2)'), ('250 vs 205 MiB', '同一个 6 秒负载下 Graal(libgraal)与 C2 的峰值常驻内存')],
    [('同一个 JDK 上的三种编译器', None), ('逃逸分析', None), ('稳态吞吐', None), ('预热曲线', None), ('资源成本', None)],
    steps, [ENV_J + '。GraalVM Community 25.0.2+10.1(JDK 25.0.2+10-jvmci-b01),macOS arm64;吞吐是 7 轮取中位数的自写循环,不是 JMH;每种负载只有一个小工作函数', '没有验证:Oracle GraalVM(含 Graal 企业版优化)、libgraal 与 jargraal 的区别、更大的真实应用与长时间运行(GC 压力下的行为)、Linux x86_64 平台、v1 / v2 / v4 / v6 没有被消除的原因(只确认了现象)、-Djdk.graal.* 的其它优化开关'], 'Graal JIT')
